import datetime,fcntl,hashlib,json,shutil,subprocess
from pathlib import Path
import psutil
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
def main():
 plan=H/'promotion-discovery-frozen-plan-nov3.json';m=json.loads(plan.read_text());state=json.loads((H/'live-nov3-promotion-discovery-custody.json').read_text());a=json.loads((H/'live-nov3-promotion-discovery-independent-analysis.json').read_text());rows=list(a['rows'].values())
 assert sha(plan)==state['manifest_sha256'];bad=[p for p,v in m['file_pins'].items() if not (ROOT/p).is_file() or sha(ROOT/p)!=v];assert not bad
 assert state['status']=='complete' and len(state['runs'])==12 and not state['owned_descendants_remaining']
 if psutil.pid_exists(state['supervisor_pid']):assert psutil.Process(state['supervisor_pid']).create_time()!=state['supervisor_create_time']
 assert all(r['owned_descendants_remaining']==[] for r in rows)
 gpu=subprocess.check_output(['nvidia-smi','--query-compute-apps=pid,process_name','--format=csv,noheader'],text=True).strip();assert not gpu
 with open('/tmp/vllm-semantic-cache-gpu.lock','a') as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);fcntl.flock(f,fcntl.LOCK_UN)
 before=shutil.disk_usage(H).free;files=[]
 for item in m['execution_order']:
  files.extend(p for p in (H/'runs'/item['name']).rglob('*') if p.is_file());files.append(H/(item['name']+'-driver-console.log.gz'))
 assert all(p.exists() for p in files);assert not any(p.suffix in ['.log','.jsonl'] for p in files)
 arms={}
 for arm in ['native','periodic','promotion_periodic','promotion_once_positive']:
  rr=[r for r in rows if r['arm']==arm];arms[arm]={'EOS':sum(r['natural_eos'] for r in rr),'generated_tokens':sum(r['tokens'] for r in rr),'hints':sum(r['cadence_receipt']['hint_rows'] for r in rr),'wait_groups':sum(r['cadence_receipt']['wait_groups'] for r in rr),'stop_markers':sum(r['cadence_receipt']['stop_markers'] for r in rr),'positive_acknowledgements':sum(r['cadence_receipt']['positive_acknowledgements'] for r in rr),'complete_acknowledgements':sum(r['cadence_receipt']['complete_acknowledgements'] for r in rr)}
 overlap={'reported_external_CPU_activity_during_measurements':None,'scope':'Root reported quiet promotion measurements; subsequent coverage tests began after all loads completed.'}
 quality={'sample_path':'live-nov3-promotion-discovery-quality-samples.json','manually_inspected':8,'unique_issue_turns':5,'selection':'Each promotion arm code-fence responses plus longest response, deduplicated. Descriptive adverse-case check, not random quality sample.','findings':['Both promotion variants reproduce Astropy fenced definition: grounded issue explanation but violates one-paragraph/no-code contract.','Both variants overclaim directory structure is correct from listing and environment incompleteness from grep missing-path warnings; these observations do not establish those broad claims.','7703/8803 samples show no completed-action claim or runaway repetition.','9901 periodic promotion SymPy sample conflates Mathematica parsing with code printing and invents an expected-versus-actual Max test absent from supplied grep evidence.','9901 once-positive MySQL sample calls timezone handling correct although supplied _convert_field_to_tz hardcodes UTC, which is the reported bug.'],'source_grounding':'Read quoted original issue and latest recorded observation in fresh-agent-nov3/session-corpus.json for all five unique issue/turns.','mechanical_inventory':{r['name']:r['service_format'] for r in rows},'degeneracy_screen_flags':sum(r['output_screen']['flagged'] for r in rows),'scope':'No quality-equivalence, accuracy, productivity or autonomous task-success claim. Baseline defects do not by themselves measure cache harm.'}
 assessment={'schema':'astra-promotion-discovery-assessment-v1','plan_sha256':sha(plan),'all_12_eligible':all(r['eligible'] for r in rows),'natural_eos':sum(r['natural_eos'] for r in rows),'HTTP':{'attempts':sum(r['HTTP_receipt']['expected_total_HTTP_requests'] for r in rows),'generations':sum(r['HTTP_receipt']['generation_rows'] for r in rows),'hints':sum(r['HTTP_receipt']['hint_rows'] for r in rows),'intentional_hint_cancellations':sum(len(r['HTTP_receipt']['intentional_hint_cancellations']) for r in rows),'unexpected_exceptions':sum(len(r['HTTP_receipt']['unexpected_transport_exceptions']) for r in rows),'connection_reuse':sum(r['HTTP_receipt']['counts']['connection_reuse'] for r in rows)},'cadence_all_causal_source_and_stop_checks_pass':all(r['cadence_receipt']['qualified'] for r in rows),'arm_cadence_and_output_totals':arms,'all_zero_preemptions':all(r['first_prefill_attribution']['preemptions']==0 for r in rows),'first_admission_reconciles_all':all(r['first_prefill_attribution']['reconciles'] is True for r in rows),'store_accept_complete_balanced_all':all(r['store_balance']['balanced'] is True for r in rows),'explicit_store_failure_counter':'Unavailable, not assumed zero.','all_measurement_configurations_match':all(r['measurement']['matches_frozen_lean'] for r in rows),'optional_observer_counts_explicit_zero':all(all(r['measurement'][k]==0 for k in ['residency_samples','readmission_events','lookup_observer_events']) for r in rows),'comparisons':a['comparisons'],'resource_and_mechanism_rows':{r['name']:{k:r[k] for k in ['load_s','tokens','tokens_s','tokens_s_per_gib','ttft_ms','e2e_ms','resources','host_resources','thermal_clock_power','first_prefill_attribution','transfers','scheduler_counts','cadence_receipt','promotion_receipt']} for r in rows},'external_CPU_activity':overlap,'quality':quality,'production_endorsement':False, 'judgment':'No consistent incremental benefit from ARC advice promotion. Periodic promotion workflow changes versus native are -3.30%, +7.48%, -0.83% across the three partitions; versus old periodic they are -0.65%, +0.29%, +2.02%. The last partition has p95 TTFT regression of 1.93s versus native and 0.79s versus old periodic. Once-positive promotion remains approximately native-like. Actual T1 promotion is sparse; most actions refresh already-T2 entries.', 'limitations':['One workflow per arm per spent input partition, incomplete four-arm Latin rotation: discovery only, no inferential confidence intervals or production endorsement.','Actual promotion counts are per-call operations excluding cached replay, not unique keys, demand hits, avoided bytes or causal attribution of timing differences.','First-admission token attribution is not cumulative physical GPU work; native transfers reported separately.','Serving NVML around7702MiB and startup7953.87MiB are unchanged; CPUKV1792MiB. Actual pinned host bytes unavailable.','Natural generated lengths differ. System-wide swap/thermal/clock counters and sampled RSS cannot uniquely attribute policy cost.','Known baseline reasoning errors and occasional format violations persist; human review required, productivity unmeasured.','Registry4096 identity saturation and continuous endurance remain unqualified.'], 'next_steps':['First perform separately frozen observation-only GPU coverage on all valid hints, including full-CPU-ready cases, to determine whether meaningful free cached GPU blocks exist to protect. Snapshot observations cannot prove future survival or causality.','If opportunity exists, a separately guarded opt-in native GPU free-queue recency policy is causally defensible but changes GPU eviction policy; requires exact identity/hash/refcount/queue-membership and ownership/integrity/invalid-hint tests, byte qualification, fresh confirmation and endurance.','True prefetch requires additional native ownership/adoption and audit-off qualification; defer until evidence supports greater cost.','A genuinely short status-draft profile without output caps is a legitimate distinct workload, but must retain all spent inputs during discovery, preserve previous negatives, and earn separate fresh-input confirmation.']}

 write(H/'live-nov3-promotion-discovery-independent-assessment.json',assessment)
 inventory={'schema':'astra-promotion-discovery-handback-v1','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'custody':'ASTRA retained by root authorization for separate three-run GPU-coverage diagnostic after read-only preflight','pins_checked':len(m['file_pins']),'pin_mismatches':bad,'supervisor_exited':True,'all_runner_descendants_exited':True,'owned_processes_remaining':[],'gpu_compute_processes':gpu,'gpu_lock_available':True,'free_bytes_before_cleanup':before,'free_bytes_after_cleanup':shutil.disk_usage(H).free,'removed_files':[],'retained_bytes':sum(p.stat().st_size for p in files),'retained_files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size} for p in files],'reason':'All raw evidence, per-run archives, compressed logs and negative outcomes preserved for independent recomputation. No disposable downloads/worktrees/checkpoints/uncompressed logs/owned processes remain; prior/shared work untouched.'};write(H/'live-nov3-promotion-discovery-handback-inventory.json',inventory)
 print(json.dumps({'HTTP':assessment['HTTP'],'arms':arms,'pins':len(m['file_pins']),'retained_bytes':inventory['retained_bytes'],'cleanup_complete':True},indent=2))
if __name__=='__main__':main()
